18	export default function ArtistsPage() {
19	  const router = useRouter()
20	  const [viewMode, setViewMode] = useState<ArtistViewMode>('grid')
21	  const [artists, setArtists] = useState<ArtistCardData[]>([])
22	  const [loading, setLoading] = useState(true)
23	  const [fetchError, setFetchError] = useState<Error | null>(null)
24	  const [showInviteModal, setShowInviteModal] = useState(false)
25	  const [filters, setFilters] = useState<ArtistFilters>({
26	    status: 'all',
27	    specialty: 'all',
28	    role: 'all',
29	  })
30	
31	  useEffect(() => {
32	    const stored = localStorage.getItem(STORAGE_KEY)
33	    if (stored === 'grid' || stored === 'table') setViewMode(stored)
34	  }, [])
35	
36	  const handleViewModeChange = (mode: ArtistViewMode) => {
37	    setViewMode(mode)
38	    localStorage.setItem(STORAGE_KEY, mode)
39	  }
40	
41	  const fetchArtists = async () => {
42	    setLoading(true)
43	    setFetchError(null)
44	    try {
45	      const res = await fetch('/api/artists')
46	      if (!res.ok) throw new Error('Failed to fetch artists')
47	      const json = await res.json() as { data: ArtistCardData[] }
48	      setArtists(json.data ?? [])
49	    } catch (err) {
50	      setFetchError(err instanceof Error ? err : new Error('Could not load artists'))
51	    } finally {
52	      setLoading(false)
53	    }
54	  }
55	
56	  useEffect(() => {
57	    void fetchArtists()
58	  }, [])
59	
60	  const allSpecialties = useMemo(() => {
61	    const set = new Set<string>()
62	    artists.forEach((a) => a.specialties.forEach((s) => set.add(s)))
63	    return [...set].sort()
64	  }, [artists])
65	
66	  const filtered = useMemo(() => {
67	    return artists.filter((a) => {
68	      if (filters.status !== 'all' && a.status !== filters.status) return false
69	      if (filters.specialty !== 'all' && filters.specialty != null && !a.specialties.includes(filters.specialty)) return false
70	      if (filters.role !== 'all' && a.role !== filters.role) return false
71	      return true
72	    })
73	  }, [artists, filters])
74	
75	  const hasActiveFilters =
76	    filters.status !== 'all' || filters.specialty !== 'all' || filters.role !== 'all'
77	
78	  const clearFilters = () =>
79	    setFilters({ status: 'all', specialty: 'all', role: 'all' })
80	
81	  const gridSkeleton = (
82	    <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-4">
83	      {Array.from({ length: 8 }).map((_, i) => (
84	        <div key={i} className="h-[168px] rounded-xl bg-muted animate-pulse" />
85	      ))}
86	    </div>
87	  )
88	
89	  return (
90	    <div className="flex flex-col min-h-0">
91	      <ArtistListHeader
92	        viewMode={viewMode}
93	        onViewModeChange={handleViewModeChange}
94	        onAddArtist={() => router.push('/artists/new')}
95	        onInviteArtist={() => setShowInviteModal(true)}
96	      />
97	
98	      <ArtistFilterBar
99	        filters={filters}
100	        onFiltersChange={setFilters}
101	        totalCount={artists.length}
102	        filteredCount={filtered.length}
103	        specialties={allSpecialties}
104	      />
105	
106	      <div className="flex-1 p-6">
107	        <DataState
108	          data={artists}
109	          isLoading={loading}
110	          isError={!!fetchError}
111	          error={fetchError}
112	          loadingSlot={gridSkeleton}
113	          emptySlot={
114	            <EmptyState
115	              icon={Users}
116	              title="No artists yet"
117	              description="Add your first artist or invite them to join your studio."
118	              cta={{ label: '+ Add Artist', onClick: () => router.push('/artists/new') }}
119	              ctaSecondary={{ label: 'Invite Artist', onClick: () => setShowInviteModal(true) }}
120	              variant="first-time"
121	            />
122	          }
123	          errorSlot={
124	            <PageError
125	              error={fetchError ?? new Error('Failed to load artists')}
126	              reset={() => void fetchArtists()}
127	              variant="inline"
128	            />
129	          }
130	        >
131	          {(_data) => (
132	            <>
133	              {hasActiveFilters && filtered.length === 0 ? (
134	                <EmptyState
135	                  icon={SearchX}
136	                  title="No artists match"
137	                  description="Try a different status, specialty, or role filter."
138	                  cta={{ label: 'Clear filters', onClick: clearFilters }}
139	                  variant="no-results"
140	                />
141	              ) : viewMode === 'grid' ? (
142	                <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-4">
143	                  {filtered.map((artist) => (
144	                    <ArtistCard key={artist.id} artist={artist} />
145	                  ))}
146	                </div>
147	              ) : (
148	                <ArtistTable
149	                  artists={filtered}
150	                  canDeactivate={true}
151	                  onDeactivate={(id) => { void id }}
152	                />
153	              )}
154	            </>
155	          )}
156	        </DataState>
157	      </div>
158	
159	      {showInviteModal && (
160	        <InviteModal
161	          open={showInviteModal}
162	          onOpenChange={setShowInviteModal}
163	          defaultRole="artist"
164	          onSuccess={() => {
165	            setShowInviteModal(false)
166	            void fetchArtists()
167	          }}
168	        />
169	      )}
170	    </div>
171	  )
172	}
