'use client'

import { usePathname, useRouter } from 'next/navigation'
import {
  SidebarGroup,
  SidebarGroupLabel,
  SidebarMenu,
  SidebarMenuButton,
  SidebarMenuItem,
} from '@/components/ui/sidebar'
import { Badge } from '@/components/ui/badge'
import { PlanBadge } from '@/components/shared/PlanBadge'
import type { NavGroup } from '@/components/app/sidebar/nav-config'
import { hasFeature } from '@/lib/billing/feature-gate'
import type { PlanTier } from '@/lib/billing/feature-gate'
import { cn } from '@/lib/utils'

interface SidebarNavGroupProps {
  group: NavGroup
  plan: PlanTier
  isFirst?: boolean
}

/**
 * S13 — Updated visual DNA per Nova density tokens:
 *  - Item height: 32px (h-8)
 *  - Icons: 16px (size-4)
 *  - Icon→label gap: 8px (gap-2)
 *  - Label: 13px / font-weight 500
 *  - Section headers: 11px uppercase tracking-wider
 *  - Active state: full bg fill (bg-primary/10 text-primary) — Notion pattern, not left-border stripe
 *
 * Plan-gated items: shown with PlanBadge (not hidden). Click navigates to /settings/billing.
 * Role-gated items: still hidden entirely (no change).
 */
export function SidebarNavGroup({ group, plan, isFirst }: SidebarNavGroupProps) {
  const pathname = usePathname()
  const router = useRouter()

  return (
    <SidebarGroup className={cn('px-0', isFirst ? 'pt-0' : 'pt-4')}>
      <SidebarGroupLabel className="mb-1 px-2.5 text-[11px] font-semibold uppercase tracking-wider text-muted-foreground/50 group-data-[collapsible=icon]:hidden">
        {group.label}
      </SidebarGroupLabel>
      <SidebarMenu className="gap-0.5">
        {group.items.map((item) => {
          const isActive =
            item.href === '/dashboard'
              ? pathname === item.href
              : pathname === item.href || pathname.startsWith(item.href + '/')

          const isGated =
            !!item.requiredPlan &&
            !hasFeature(plan, item.featureKey ?? item.requiredPlan)

          function handleClick() {
            if (isGated) {
              router.push('/settings/billing')
              return
            }
            router.push(item.href)
          }

          return (
            <SidebarMenuItem key={item.href}>
              <SidebarMenuButton
                // Use button render when gated so click can redirect to billing
                render={isGated ? <button type="button" /> : <a href={item.href} />}
                isActive={isActive}
                onClick={isGated ? handleClick : undefined}
                className={cn(
                  'group/item relative h-8 gap-2 rounded-md px-2.5 text-[13px] font-medium transition-all duration-150',
                  // Inactive state
                  'text-sidebar-foreground/65 hover:bg-sidebar-accent/40 hover:text-sidebar-foreground',
                  // S13: Full bg fill active state (Notion pattern) — replaces left-border stripe
                  'data-[active=true]:bg-primary/10 data-[active=true]:text-primary data-[active=true]:font-semibold',
                  // Gated: reduced opacity
                  isGated && 'opacity-60',
                )}
                tooltip={item.label}
              >
                <item.icon
                  className={cn(
                    '!h-4 !w-4 shrink-0 transition-opacity',
                    isActive ? 'opacity-100' : 'opacity-55 group-hover/item:opacity-80',
                  )}
                  aria-hidden="true"
                />
                <span className="truncate group-data-[collapsible=icon]:hidden">
                  {item.label}
                </span>
                {/* Plan badge — shown for gated items (not hidden) */}
                {isGated && item.requiredPlan && item.requiredPlan !== 'solo' && (
                  <PlanBadge
                    plan={item.requiredPlan}
                    className="ml-auto group-data-[collapsible=icon]:hidden"
                  />
                )}
                {/* New/Beta badge — only when not gated */}
                {item.badge && !isGated && (
                  <Badge
                    variant="outline"
                    className="ml-auto h-[17px] border-emerald-500/25 bg-success/10 px-1.5 py-0 text-[9px] font-semibold tracking-wide text-success group-data-[collapsible=icon]:hidden"
                  >
                    {item.badge === 'new' ? 'New' : 'Beta'}
                  </Badge>
                )}
              </SidebarMenuButton>
            </SidebarMenuItem>
          )
        })}
      </SidebarMenu>
    </SidebarGroup>
  )
}

