interface AppointmentsPageClientProps {
  /**
   * When true, forces the appointments table to filter to today's date.
   * Used by the "Today" tab on the /appointments tab host page.
   */
  forceToday?: boolean
}

export function AppointmentsPageClient({ forceToday }: AppointmentsPageClientProps) {
  const queryClient = useQueryClient()
  const router = useRouter()
  const [drawerOpen, setDrawerOpen] = useState(false)
  const searchParams = useSearchParams()

  // M2: wire ?date=today param — also overridden by forceToday prop (S13 "Today" tab)
  const dateParam = searchParams.get('date')
  const initialDateFilter: 'today' | undefined =
    forceToday === true || dateParam === 'today' ? 'today' : undefined

  // Bulk action state
  const [bulkRescheduleOpen, setBulkRescheduleOpen] = useState(false)
  const [bulkCancelOpen, setBulkCancelOpen] = useState(false)
  const [bulkAppointments, setBulkAppointments] = useState<BulkAppointmentItem[]>([])

  // Detail drawer state
  const [detailOpen, setDetailOpen] = useState(false)
  const [detailAppointmentId, setDetailAppointmentId] = useState<string | undefined>(undefined)

  return (
    <PullToRefresh
      onRefresh={async () => {
        router.refresh()
        await queryClient.invalidateQueries({ queryKey: ['bookings'] })
      }}
      className="flex flex-col flex-1 overflow-hidden h-full"
    >
      <AppointmentsTable
        onNewAppointment={() => setDrawerOpen(true)}
        initialDateFilter={initialDateFilter}
        onBulkReschedule={(appointments) => {
          setBulkAppointments(appointments)
          setBulkRescheduleOpen(true)
        }}
        onBulkCancel={(appointments) => {
          setBulkAppointments(appointments)
          setBulkCancelOpen(true)
        }}
        onRowClick={(id) => {
          setDetailAppointmentId(id)
          setDetailOpen(true)
        }}
      />

      <AppointmentCreateDrawer
        open={drawerOpen}
        onOpenChange={setDrawerOpen}
        editingId={null}
        onSuccess={() => {
          setDrawerOpen(false)
          void queryClient.invalidateQueries({ queryKey: ['bookings'] })
        }}
      />

      <BulkRescheduleSheet
        open={bulkRescheduleOpen}
        onOpenChange={setBulkRescheduleOpen}
        appointments={bulkAppointments}
        onSuccess={() => {
          setBulkAppointments([])
          void queryClient.invalidateQueries({ queryKey: ['bookings'] })
        }}
      />

      <BulkCancelSheet
        open={bulkCancelOpen}
        onOpenChange={setBulkCancelOpen}
        appointments={bulkAppointments}
        onSuccess={() => {
          setBulkAppointments([])
          void queryClient.invalidateQueries({ queryKey: ['bookings'] })
        }}
      />

      <AppointmentDetailDrawer
        open={detailOpen}
        onOpenChange={setDetailOpen}
        appointmentId={detailAppointmentId}
      />
    </PullToRefresh>
  )
}

