import { useState, useEffect, useMemo } from 'react'
import { useRouter } from 'next/navigation'
import { Users, SearchX } from 'lucide-react'
import { ArtistCard } from '@/components/artists/ArtistCard'
import { ArtistTable } from '@/components/artists/ArtistTable'
import { ArtistListHeader, type ArtistViewMode } from '@/components/artists/ArtistListHeader'
import { ArtistFilterBar, type ArtistFilters } from '@/components/artists/ArtistFilterBar'
import { InviteModal } from '@/components/settings/team/InviteModal'
import { DataState } from '@/components/shared/DataState'
import { EmptyState } from '@/components/shared/EmptyState'
import { PageError } from '@/components/shared/PageError'
import type { ArtistCardData } from '@/components/artists/ArtistCard'

const STORAGE_KEY = 'inkos:artists:view'

/**
 * S13 — Extracted from former /artists/page.tsx (which was a pure client component).
 * Now used as the "Roster" tab content inside the /artists tab host server page.
 */
export function ArtistsRosterClient() {
  const router = useRouter()
  const [viewMode, setViewMode] = useState<ArtistViewMode>('grid')
  const [artists, setArtists] = useState<ArtistCardData[]>([])
  const [loading, setLoading] = useState(true)
  const [fetchError, setFetchError] = useState<Error | null>(null)
  const [showInviteModal, setShowInviteModal] = useState(false)
  const [filters, setFilters] = useState<ArtistFilters>({
    status: 'all',
    specialty: 'all',
    role: 'all',
  })

  useEffect(() => {
    const stored = localStorage.getItem(STORAGE_KEY)
    if (stored === 'grid' || stored === 'table') setViewMode(stored)
  }, [])

  const handleViewModeChange = (mode: ArtistViewMode) => {
    setViewMode(mode)
    localStorage.setItem(STORAGE_KEY, mode)
  }

  const fetchArtists = async () => {
    setLoading(true)
    setFetchError(null)
    try {
      const res = await fetch('/api/artists')
      if (!res.ok) throw new Error('Failed to fetch artists')
      const json = await res.json() as { data: ArtistCardData[] }
      setArtists(json.data ?? [])
    } catch (err) {
      setFetchError(err instanceof Error ? err : new Error('Could not load artists'))
    } finally {
      setLoading(false)
    }
  }

  useEffect(() => {
    void fetchArtists()
  }, [])

  const allSpecialties = useMemo(() => {
    const set = new Set<string>()
    artists.forEach((a) => a.specialties.forEach((s) => set.add(s)))
    return [...set].sort()
  }, [artists])

  const filtered = useMemo(() => {
    return artists.filter((a) => {
      if (filters.status !== 'all' && a.status !== filters.status) return false
      if (filters.specialty !== 'all' && filters.specialty != null && !a.specialties.includes(filters.specialty)) return false
      if (filters.role !== 'all' && a.role !== filters.role) return false
      return true
    })
  }, [artists, filters])

  const hasActiveFilters =
    filters.status !== 'all' || filters.specialty !== 'all' || filters.role !== 'all'

  const clearFilters = () =>
    setFilters({ status: 'all', specialty: 'all', role: 'all' })

  const gridSkeleton = (
    <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-4">
      {Array.from({ length: 8 }).map((_, i) => (
        <div key={i} className="h-[168px] rounded-xl bg-muted animate-pulse" />
      ))}
    </div>
  )

  return (
    <div className="flex flex-col min-h-0">
      <ArtistListHeader
        viewMode={viewMode}
        onViewModeChange={handleViewModeChange}
        onAddArtist={() => router.push('/artists/new')}
        onInviteArtist={() => setShowInviteModal(true)}
      />

      <ArtistFilterBar
        filters={filters}
        onFiltersChange={setFilters}
        totalCount={artists.length}
        filteredCount={filtered.length}
        specialties={allSpecialties}
      />

      <div className="flex-1 p-6">
        <DataState
          data={artists}
          isLoading={loading}
          isError={!!fetchError}
          error={fetchError}
          loadingSlot={gridSkeleton}
          emptySlot={
            <EmptyState
              icon={Users}
              title="No artists yet"
              description="Add your first artist or invite them to join your studio."
              cta={{ label: '+ Add Artist', onClick: () => router.push('/artists/new') }}
              ctaSecondary={{ label: 'Invite Artist', onClick: () => setShowInviteModal(true) }}
              variant="first-time"
            />
          }
          errorSlot={
            <PageError
              error={fetchError ?? new Error('Failed to load artists')}
              reset={() => void fetchArtists()}
              variant="inline"
            />
          }
        >
          {(_data) => (
            <>
              {hasActiveFilters && filtered.length === 0 ? (
                <EmptyState
                  icon={SearchX}
                  title="No artists match"
                  description="Try a different status, specialty, or role filter."
                  cta={{ label: 'Clear filters', onClick: clearFilters }}
                  variant="no-results"
                />
              ) : viewMode === 'grid' ? (
                <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-4">
                  {filtered.map((artist) => (
                    <ArtistCard key={artist.id} artist={artist} />
                  ))}
                </div>
              ) : (
                <ArtistTable
                  artists={filtered}
                  canDeactivate={true}
                  onDeactivate={(id) => { void id }}
                />
              )}
            </>
          )}
        </DataState>
      </div>

      {showInviteModal && (
        <InviteModal
          open={showInviteModal}
          onOpenChange={setShowInviteModal}
          defaultRole="artist"
          onSuccess={() => {
            setShowInviteModal(false)
            void fetchArtists()
          }}
        />
      )}
    </div>
  )
}

