'use client'

import Link from 'next/link'
import { usePathname } from 'next/navigation'
import { LayoutDashboard, CalendarDays, Users, Plus, MoreHorizontal } from 'lucide-react'
import { cn } from '@/lib/utils'

/**
 * S13 — Updated 5-slot bottom navigation bar for mobile.
 * Slots: Home / Schedule / + New (center FAB) / Clients / More
 *
 * Changes from B12:
 *  - Renamed prop: onNewAppointment → onNew (broadened: opens create menu, not just appointment)
 *  - New prop: onMoreOpen — opens the MobileNav sheet
 *  - "Settings" right slot replaced by "More" (triggers MobileNav sheet)
 *  - "Dashboard" left slot label updated to "Home"
 *  - "Schedule" routes to /calendar
 *  - Active state: icon + label in primary color
 *  - isActive guard: empty href returns false (More slot)
 */

interface BottomNavProps {
  /** Opens the quick-create menu (appointment, client, consent, invite) */
  onNew: () => void
  /** Opens the MobileNav full-tree sheet */
  onMoreOpen: () => void
}

interface NavSlot {
  icon: React.ComponentType<{ className?: string }>
  label: string
  href: string
}

const LEFT_SLOTS: NavSlot[] = [
  { icon: LayoutDashboard, label: 'Home',     href: '/dashboard' },
  { icon: CalendarDays,    label: 'Schedule', href: '/calendar' },
]

const RIGHT_SLOTS: NavSlot[] = [
  { icon: Users,          label: 'Clients', href: '/clients' },
  // More slot — href is empty, rendered as button via MoreButton component
  { icon: MoreHorizontal, label: 'More',    href: '' },
]

export function BottomNav({ onNew, onMoreOpen }: BottomNavProps) {
  const pathname = usePathname()

  function isActive(href: string) {
    if (!href) return false
    if (href === '/dashboard') return pathname === '/dashboard'
    return pathname.startsWith(href)
  }

  return (
    <nav
      aria-label="Primary navigation"
      className={cn(
        'flex md:hidden',
        'fixed bottom-0 left-0 right-0 z-40',
        'h-16 pb-safe',
        'bg-background/95 backdrop-blur-md',
        'border-t border-border/60',
        'shadow-[0_-1px_0_0_hsl(var(--border)/0.5)]',
      )}
    >
      {/* Left 2 slots */}
      {LEFT_SLOTS.map((slot) => (
        <NavLink key={slot.href} slot={slot} active={isActive(slot.href)} />
      ))}

      {/* Center FAB — primary create action */}
      <div className="flex flex-1 items-center justify-center">
        <button
          type="button"
          onClick={onNew}
          aria-label="New"
          className={cn(
            'flex flex-col items-center justify-center',
            'h-14 w-14 rounded-full',
            '-translate-y-4',
            'bg-primary text-primary-foreground',
            'shadow-[var(--shadow-soft-md,var(--shadow-card))]',
            'transition-transform active:scale-95',
            'touch-manipulation',
          )}
        >
          <Plus className="h-6 w-6" aria-hidden="true" />
        </button>
      </div>

      {/* Right 2 slots */}
      <NavLink slot={RIGHT_SLOTS[0]!} active={isActive(RIGHT_SLOTS[0]!.href)} />
      <MoreButton onMoreOpen={onMoreOpen} />
    </nav>
  )
}

function NavLink({ slot, active }: { slot: NavSlot; active: boolean }) {
  const { icon: Icon, label, href } = slot
  return (
    <Link
      href={href}
      className={cn(
        'flex flex-1 flex-col items-center justify-center gap-1',
        'min-h-[44px] min-w-[44px]',
        'transition-colors duration-150',
        active ? 'text-primary' : 'text-muted-foreground hover:text-foreground',
      )}
      aria-current={active ? 'page' : undefined}
    >
      <Icon className="h-5 w-5 shrink-0" aria-hidden="true" />
      <span className="text-[10px] font-medium tracking-tight leading-none">{label}</span>
    </Link>
  )
}

